import{_ as s,C as r,c as n,o as l,ag as a,j as t,G as o}from"./chunks/framework.Bw-5EFTY.js";const b=JSON.parse('{"title":"How to Register as an Affiliate","description":"","frontmatter":{},"headers":[],"relativePath":"guide/affiliate-portal/how-to-register-as-an-affiliate.md","filePath":"guide/affiliate-portal/how-to-register-as-an-affiliate.md","lastUpdated":1752482039000}'),p={name:"guide/affiliate-portal/how-to-register-as-an-affiliate.md"};function f(h,e,g,d,c,u){const i=r("ZoomableImage");return l(),n("div",null,[e[0]||(e[0]=a('<h1 id="how-to-register-as-an-affiliate" tabindex="-1">How to Register as an Affiliate <a class="header-anchor" href="#how-to-register-as-an-affiliate" aria-label="Permalink to &quot;How to Register as an Affiliate&quot;">​</a></h1><p>Becoming an affiliate on your site using <strong>Fluent Affiliate</strong> is easy. Whether someone is a long time promoter or just starting their journey, the registration process is quick, simple, and designed for ease.</p><p>Let&#39;s walk through how a user can register and get started as an affiliate.</p><h3 id="step-1-access-the-affiliate-dashboard" tabindex="-1">Step 1: Access the Affiliate Dashboard <a class="header-anchor" href="#step-1-access-the-affiliate-dashboard" aria-label="Permalink to &quot;Step 1: Access the Affiliate Dashboard&quot;">​</a></h3><p>When a user visits your site&#39;s <strong>Affiliate Page</strong> usually linked in the menu or footer, they&#39;ll see a simple, user friendly interface. From here, they can log in to their affiliate dashboard or click the <strong>Register</strong> button to sign up and become an affiliate.</p><p>Click the <strong>Register Now</strong> button to start the sign-up process.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Only the site admin can decide where the <strong>Affiliate Page</strong> appears on the site. To learn how to set this up, check out this <a href="/guide/settings-and-customization/referral-settings">article</a>.</p></div>',7)),t("p",null,[o(i,{src:"/guide/public/images/affiliate-portal/registration/registration-page.webp",alt:"Affiliate Registration Page"})]),e[1]||(e[1]=a('<h3 id="step-2-fill-out-the-registration-form" tabindex="-1">Step 2: Fill Out the Registration Form <a class="header-anchor" href="#step-2-fill-out-the-registration-form" aria-label="Permalink to &quot;Step 2: Fill Out the Registration Form&quot;">​</a></h3><p>After clicking <strong>Register Now</strong>, users will land on the Affiliate Registration page. Here, they&#39;ll be asked to provide the necessary details to create their affiliate account. It is divided into clear sections for ease of use.</p><p><strong>Account Information</strong></p><p>This section covers the basic details needed to create the account:</p><ul><li><strong>Full name</strong></li><li><strong>Email Address</strong></li><li><strong>Username</strong></li><li><strong>Account Password</strong></li></ul><p><strong>About Yourself</strong></p><p>This part of the form helps the site owner understand more about their potential partners:</p><ul><li><strong>How will you promote us?:</strong> A field to describe marketing methods and strategies.</li><li><strong>Website URL:</strong> The user&#39;s blog or website link, which helps verify their online presence.</li><li><strong>Payment Email Address:</strong> The affiliate&#39;s PayPal email where their future commission payments will be sent.</li></ul><p><strong>Final Agreement and Submission</strong></p><p>To complete the process, the user must:</p><ol><li><p>Check the box to confirm they &quot;<strong>I agree to the terms and conditions.</strong>&quot;</p></li><li><p>Click the <strong>Register</strong> button to submit their application for review.</p></li></ol>',11)),t("p",null,[o(i,{src:"/guide/public/images/affiliate-portal/registration/registration-form.webp",alt:"Registration Form"})]),e[2]||(e[2]=a('<h3 id="step-3-welcome-to-the-affiliate-dashboard" tabindex="-1">Step 3: Welcome to the Affiliate Dashboard <a class="header-anchor" href="#step-3-welcome-to-the-affiliate-dashboard" aria-label="Permalink to &quot;Step 3: Welcome to the Affiliate Dashboard&quot;">​</a></h3><p>After the user submits the form and their application is approved by the <strong>site admin</strong>, they can log in. Upon logging in, they will be directed to their personal <strong>Affiliate Dashboard</strong>.</p><p>This dashboard is their central hub to:</p><ul><li><p>Track performance, including visits, referrals, and earnings.</p></li><li><p>Generate unique affiliate links for promoting products.</p></li><li><p>View their history of payouts.</p></li><li><p>Update their account settings.</p></li></ul><p>To learn more about the Affiliate Dashboard, check out this <a href="/guide/affiliate-portal/affiliate-dashboard-overview">article</a>.</p>',5)),t("p",null,[o(i,{src:"/guide/public/images/affiliate-portal/registration/registration-success.webp",alt:"Affiliate Dashboard"})]),e[3]||(e[3]=t("p",null,"And that's it! In just a few simple steps, a new user can join the affiliate program and get everything they need to start promoting and earning.",-1))])}const _=s(p,[["render",f]]);export{b as __pageData,_ as default};
